// Generate extraction requests for all 6 panels with explicit numbered positions
const sourceUrl = $input.first().json.contact_sheet_image[0].url;
const projectName = $input.first().json['Project Name'];

// Much more explicit prompts using numbered grid positions and pixel descriptions
const panels = [
  {
    panel_index: 1,
    name: 'Panel 1 (Row 1, Col 1)',
    prompt: `This image contains a 3x2 grid of 6 photos arranged in 2 rows and 3 columns, separated by thin black borders. Extract ONLY the photo in position 1 (top-left corner). This is the leftmost photo in the top row. Crop it precisely at the black border edges. Output only this single rectangular photo with no borders, no other panels, no grid lines. Do not include any part of the adjacent photos.`
  },
  {
    panel_index: 2,
    name: 'Panel 2 (Row 1, Col 2)',
    prompt: `This image contains a 3x2 grid of 6 photos arranged in 2 rows and 3 columns, separated by thin black borders. Extract ONLY the photo in position 2 (top-center). This is the middle photo in the top row, between the left and right photos. Crop it precisely at the black border edges. Output only this single rectangular photo with no borders, no other panels, no grid lines.`
  },
  {
    panel_index: 3,
    name: 'Panel 3 (Row 1, Col 3)',
    prompt: `This image contains a 3x2 grid of 6 photos arranged in 2 rows and 3 columns, separated by thin black borders. Extract ONLY the photo in position 3 (top-right corner). This is the rightmost photo in the top row. Crop it precisely at the black border edges. Output only this single rectangular photo with no borders, no other panels, no grid lines.`
  },
  {
    panel_index: 4,
    name: 'Panel 4 (Row 2, Col 1)',
    prompt: `This image contains a 3x2 grid of 6 photos arranged in 2 rows and 3 columns, separated by thin black borders. Extract ONLY the photo in position 4 (bottom-left corner). This is the leftmost photo in the bottom row. Crop it precisely at the black border edges. Output only this single rectangular photo with no borders, no other panels, no grid lines.`
  },
  {
    panel_index: 5,
    name: 'Panel 5 (Row 2, Col 2)',
    prompt: `This image contains a 3x2 grid of 6 photos arranged in 2 rows and 3 columns, separated by thin black borders. Extract ONLY the photo in position 5 (bottom-center). This is the middle photo in the bottom row. Crop it precisely at the black border edges. Output only this single rectangular photo with no borders, no other panels, no grid lines.`
  },
  {
    panel_index: 6,
    name: 'Panel 6 (Row 2, Col 3)',
    prompt: `This image contains a 3x2 grid of 6 photos arranged in 2 rows and 3 columns, separated by thin black borders. Extract ONLY the photo in position 6 (bottom-right corner). This is the rightmost photo in the bottom row. Crop it precisely at the black border edges. Output only this single rectangular photo with no borders, no other panels, no grid lines.`
  }
];

return panels.map(p => ({
  json: {
    ...p,
    source_url: sourceUrl,
    project_name: projectName
  }
}));

// Validate extraction results and prepare for retry or continuation
const items = $input.all();
const successful = [];
const failed = [];

for (const item of items) {
  const panelIndex = item.json.panel_index;
  const outputUrl = item.json.data?.outputs?.[0];

  if (outputUrl && outputUrl.startsWith('http')) {
    successful.push({
      json: {
        panel_index: panelIndex,
        panel_name: item.json.name,
        output_url: outputUrl,
        project_name: item.json.project_name,
        status: 'success'
      }
    });
  } else {
    failed.push({
      json: {
        panel_index: panelIndex,
        panel_name: item.json.name,
        error: item.json.error || 'No output URL returned',
        project_name: item.json.project_name,
        status: 'failed',
        // Include original request data for retry
        source_url: item.json.source_url,
        prompt: item.json.prompt
      }
    });
  }
}

// Log validation results
console.log(`Validation: ${successful.length}/6 successful, ${failed.length}/6 failed`);

if (failed.length > 0) {
  console.log('Failed panels:', failed.map(f => f.json.panel_index).join(', '));
}

// Return successful items (failed go to error output)
return successful;

// Collect all successful extractions and create scene transitions
const items = $input.all();

// Sort by panel index
const sortedPanels = items
  .map(item => item.json)
  .sort((a, b) => a.panel_index - b.panel_index);

// Check if we have enough panels for scene creation
if (sortedPanels.length < 2) {
  throw new Error(`Need at least 2 panels to create scenes, got ${sortedPanels.length}`);
}

// Create scene transitions for consecutive panels
const scenes = [];
for (let i = 0; i < sortedPanels.length - 1; i++) {
  scenes.push({
    json: {
      scene_number: i + 1,
      start_image_url: sortedPanels[i].output_url,
      end_image_url: sortedPanels[i + 1].output_url,
      start_panel: sortedPanels[i].panel_index,
      end_panel: sortedPanels[i + 1].panel_index,
      project_name: sortedPanels[0].project_name,
      transition_prompt: "The camera performs a very slow, smooth, continuous movement with no acceleration or shake. The subject barely moves and remains extremely deliberate and thoughtful in movement.",
      panels_extracted: sortedPanels.length,
      scenes_created: sortedPanels.length - 1
    }
  });
}

return scenes;
